import { mDNS } from 'capacitor-mdns';

// Start advertising
await mDNS.startBroadcast({ type: '_http._tcp.', name: 'my.app.id', port: 9235 });

// Discover services
const { services } = await mDNS.discover({ type: '_http._tcp.', timeout: 3000 });

// Stop advertising
await mDNS.stopBroadcast();
